                          OnMoveRight="OnMoveRight" />
            }
            <AddTaskForm Status="@Status"
                         TaskService="TaskService"
                         OnTaskCreated="OnTaskCreated" />
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = default!;
    [Parameter, EditorRequired] public string Status { get; set; } = default!;
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<int> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<int> OnMoveRight { get; set; }
    [Parameter] public EventCallback<TaskItem> OnTaskCreated { get; set; }
    [Parameter, EditorRequired] public ITaskService TaskService { get; set; } = default!;
}

@page "/board"
@using sv_6c46e89767ea45a2802c8cb8b9956cac.Components.Board
@using sv_6c46e89767ea45a2802c8cb8b9956cac.Services
@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (isLoading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-link" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardSummaryBar AllTasks="allTasks" />

    <BoardSearchBar SearchTerm="@searchTerm" SearchTermChanged="OnSearchChanged" />

    <div class="row g-3">
        <div class="col-md-4">
            <KanbanColumn ColumnName="To Do"
                          Status="To Do"
                          Tasks="GetFilteredTasks(\"To Do\")"
                          CanMoveLeft="false"
                          CanMoveRight="true"
                          OnMoveRight="@(id => MoveTask(id, "In Progress"))"
                          OnTaskCreated="OnTaskCreated"
                          TaskService="TaskService" />
        </div>
        <div class="col-md-4">
            <KanbanColumn ColumnName="In Progress"
                          Status="In Progress"
                          Tasks="GetFilteredTasks(\"In Progress\")"
                          CanMoveLeft="true"
                          CanMoveRight="true"
                          OnMoveLeft="@(id => MoveTask(id, "To Do"))"
                          OnMoveRight="@(id => MoveTask(id, "Done"))"
                          OnTaskCreated="OnTaskCreated"
                          TaskService="TaskService" />
        </div>
        <div class="col-md-4">
            <KanbanColumn ColumnName="Done"
                          Status="Done"
                          Tasks="GetFilteredTasks(\"Done\")"
                          CanMoveLeft="true"
                          CanMoveRight="false"
                          OnMoveLeft="@(id => MoveTask(id, "In Progress"))"
                          OnTaskCreated="OnTaskCreated"
                          TaskService="TaskService" />
        </div>
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchTerm = "";
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var filtered = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            filtered = filtered.Where(t => t.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
        }
        return filtered.ToList();
    }

    private void OnSearchChanged(string value)
    {
        searchTerm = value;
    }

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = allTasks.FirstOrDefault(t => t.Id == taskId);
            if (task is not null)
            {
                allTasks = allTasks.Select(t => t.Id == taskId ? t with { Status = newStatus } : t).ToList();
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private void OnTaskCreated(TaskItem newTask)
    {
        allTasks.Add(newTask);
    }
}

